class NewsUpdater: NSObject {
    // MARK: - Properties
    private let userDefaults = UserDefaults.standard

    private var location: CLLocation?

    private var newsUpdates: [NewsUpdate] = []

    // MARK: - Initializers
    init() {
        super.init()

        // Register for location updates
        locationManager = CLLocationManager()
        locationManager?.desiredAccuracy =.high
        locationManager?.distanceFilter = 1000
        locationManager?.delegate = self
        locationManager?.requestWhenInUseAuthorization()
        locationManager?.requestAlwaysAuthorization()
    }

    // MARK: - Life Cycle
    deinit {
        // Stop location updates
        locationManager?.stopUpdatingLocation()
    }

    // MARK: - Methods
    func updateNews() {
        // Get user location
        if locationManager?.location?.coordinate!= nil {
            // Update news updates based on location
            let userLocation = locationManager?.location?.coordinate
            let newsUpdates = getNewsUpdates(for: userLocation)
            self.newsUpdates = newsUpdates
        }
    }

    // MARK: - Private Methods
    private func getNewsUpdates(for userLocation: CLLocationCoordinate2D?) -> [NewsUpdate] {
        // Get news updates from API
        let newsUpdates = [NewsUpdate]()
        return newsUpdates
    }
}

// MARK: - Protocol
extension NewsUpdater: CLLocationManagerDelegate {
    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        // Update location
        location = locations.last
        updateNews()
    }
}

